CREATE TABLE "Notifications" ("IdNotification" integer NOT NULL GENERATED BY DEFAULT AS IDENTITY ( INCREMENT 1 START 1 MINVALUE 1 MAXVALUE 2147483647 CACHE 1 ), "IdProfesseur" integer NOT NULL, "Titre" character varying(200) COLLATE pg_catalog."default" NOT NULL, "Message" text COLLATE pg_catalog."default" NOT NULL, "Type" character varying(50) COLLATE pg_catalog."default" NOT NULL, "Lien" character varying(500) COLLATE pg_catalog."default", "EstLue" boolean NOT NULL, "DateCreation" timestamp with time zone NOT NULL, "DateLecture" timestamp with time zone, CONSTRAINT "PK_Notifications" PRIMARY KEY ("IdNotification"));
